package com.cbdog.ptvbox
import org.junit.Test
import org.junit.Assert.*
class Version052Test {
 @Test fun rememberedSiteOutranksGroupPriority(){val a=Site("a","A","https://example.org",group="high");val b=a.copy(key="b",group="low");val w=Watch(Work("w","片"),"正片","b","1080p",1080,5000,10000);assertEquals("b",Variant052.order(listOf(a,b),w){if(it=="high")0 else 9}.first().key)}
 @Test fun changedStreamArrayNumberDoesNotLoseVersion(){assertTrue(Variant052.same("HDHUB · 1080p 2GB · #31","HDHUB · 1080p 2GB · #4"));assertFalse(Variant052.same("HDHUB · 1080p 2GB · #31","HDHUB · 720p 2GB · #31"));assertFalse(Variant052.same("HDHUB · 1080p 2GB","HDHUB · 1080p 39GB"))}
 @Test fun previousVodIdComesOnlyFromSameSite(){val w=Watch(Work("w","片"),"1","s","r",1080,1000,10000,sourceId="s|vod42|r");assertEquals("vod42",Variant052.previousId(w));assertNull(Variant052.previousId(w.copy(sourceId="other|vod42|r")))}
 @Test fun embeddedPlaybackPagesKeepRelativeIframeAndEscapedMedia(){val links=WebMedia052.embedded("""<iframe src='/player/a'></iframe><script>var u='https:\/\/cdn.example.org\/a.m3u8?token=x';</script>""","https://example.org/match/42");assertTrue(links.contains("https://example.org/player/a"));assertTrue(links.contains("https://cdn.example.org/a.m3u8?token=x"));assertFalse(WebMedia052.mediaUrl("https://example.org/ad/promo.mp4"))}
 @Test fun mediaProbeRejectsHtmlButAcceptsTransportAndFlv(){assertFalse(MediaBytes052.accept("<html>error</html>".toByteArray()));assertTrue(MediaBytes052.accept("#EXTM3U\n#EXTINF:6\n1.ts".toByteArray()));assertTrue(MediaBytes052.accept(ByteArray(20).also{it[0]=70;it[1]=76;it[2]=86}))}
 @Test fun headerDatesAreNotMatches(){assertTrue(LiveParser050.directoryLabel(Vod("x","2026-11-22","","","",emptyList())));assertFalse(LiveParser050.directoryLabel(Vod("x","20:30 曼城 VS 富勒姆","","","",emptyList())))}
 @Test fun portalContainsAllSavedServiceInputsAndShowsLinks(){val ids=ConfigPortal052.fields.map{it.id};assertEquals(ids.size,ids.distinct().size);assertTrue(ids.containsAll(SettingsInventory.serviceSecrets));assertEquals("link",ConfigPortal052.fields.first{it.id=="danmaku_url"}.kind);assertEquals("secret",ConfigPortal052.fields.first{it.id=="opensub_password"}.kind);assertEquals("remote",SettingsInventory.sections.first().id)}
 @Test fun remoteCannotWriteUnknownPreferencesOrInvalidOptions(){val f=ConfigPortal052.fields.first{it.id=="search_parallel"};assertThrows(IllegalArgumentException::class.java){ConfigPortal052.validate(f,"999")};ConfigPortal052.validate(f,"20");assertNull(ConfigPortal052.fields.firstOrNull{it.id=="hide_sensitive"});assertThrows(IllegalArgumentException::class.java){ConfigPortal052.validate(ConfigPortal052.fields.first{it.id=="live_subscription"},"file:///private")}}
 @Test fun unsupportedMain10DoesNotAutoSelectButKeepsOrdinaryVersions(){assertFalse(DecodeSupport052.compatible("720p 10Bit HEVC x265",false));assertTrue(DecodeSupport052.compatible("1080p x264",false));assertTrue(DecodeSupport052.compatible("1080p 10bit HEVC HDR",true));assertTrue(DecodeSupport052.compatible("1080p HEVC",false))}
 @Test fun liveCompatibilityKeepsStableSiteKeysAndDoesNotEmptyExistingSources(){val sports=Site("sport","吃瓜看球","csp_LiveGzGuard",3);val aggregate=Site("all","一直播","csp_AllliveGuard",3,ext="fixture");val huya=Site("huya","虎牙直播","https://example.org/drpy2.js",3);val sources=LiveParser050.sources("{}","",listOf(sports,aggregate,huya));assertEquals(3,sources.size);assertEquals("huya",sources.last().site!!.key);assertEquals("csp_AllliveGuard",sources.last().site!!.api);assertEquals("虎牙",sources.last().platform)}
 @Test fun pluginFolderTagSurvivesParserAndTransport(){val folder=VodParser.parse(org.json.JSONObject("""{"vod_id":"huya-1","vod_name":"英雄联盟","vod_tag":"folder"}"""));assertTrue(folder.folder);assertTrue(VodWire.decode(VodWire.encode(folder)).folder);assertTrue(LiveParser050.folder(Site("s","网络直播","csp_Live",3),folder))}
 @Test fun pendingMatchTitleIsNotTreatedAsBrokenLiveVideo(){assertTrue(LiveParser050.awaitingSignal(Vod("1","23:00 考文垂 VS 水晶宫 未开始","","","",emptyList())));assertTrue(LiveParser050.awaitingSignal(Vod("2","02:00 76人 VS 雄鹿 暂无","","","",emptyList())));assertFalse(LiveParser050.awaitingSignal(Vod("3","未开始的挑战 · 游戏直播","","","直播中",emptyList())))}
}
